1	import type { UserSetting_TagMetadata, UserSetting_TagsSetting } from "@/types/proto/api/v1/user_service_pb";
2	
3	// Cache compiled regexes to avoid re-compiling on every tag render.
4	const compiledPatternCache = new Map<string, RegExp | null>();
5	
6	const getCompiledPattern = (pattern: string): RegExp | null => {
7	  if (compiledPatternCache.has(pattern)) {
8	    return compiledPatternCache.get(pattern)!;
9	  }
10	  let re: RegExp | null = null;
11	  try {
12	    re = new RegExp(`^(?:${pattern})$`);
13	  } catch {
14	    // Invalid pattern — cache as null so we skip it without retrying.
15	  }
16	  compiledPatternCache.set(pattern, re);
17	  return re;
18	};
19	
20	/**
21	 * Finds the first matching TagMetadata for a given tag name by treating each
22	 * key in tagsSetting.tags as an anchored regex pattern (^pattern$).
23	 *
24	 * Lookup order:
25	 * 1. Exact key match (O(1) fast path, backward-compatible).
26	 * 2. Iterate all keys and test as anchored regex — first match wins.
27	 */
28	export const findTagMetadata = (tag: string, tagsSetting: UserSetting_TagsSetting): UserSetting_TagMetadata | undefined => {
29	  // Fast path: exact match.
30	  if (tagsSetting.tags[tag]) {
31	    return tagsSetting.tags[tag];
32	  }
33	
34	  // Regex path: treat each key as an anchored pattern.
35	  for (const [pattern, metadata] of Object.entries(tagsSetting.tags)) {
36	    const re = getCompiledPattern(pattern);
37	    if (re?.test(tag)) {
38	      return metadata;
39	    }
40	  }
41	
42	  return undefined;
43	};
44	
45	/**
46	 * Returns true if the given string is a valid, ReDoS-safe JavaScript regex pattern.
47	 *
48	 * Rejects patterns with nested quantifiers (e.g. `(a+)+`) which can cause
49	 * catastrophic backtracking in JavaScript's regex engine.
50	 */
51	export const isValidTagPattern = (pattern: string): boolean => {
52	  if (!pattern) return false;
53	  try {
54	    new RegExp(pattern);
55	  } catch {
56	    return false;
57	  }
58	  // Reject nested quantifiers: a quantified group whose body itself contains
59	  // a quantifier — the classic ReDoS shape e.g. (a+)+, (a*b?)+, (x|y+)+.
60	  if (/\((?:[^()]*[*+?{][^()]*)\)[*+?{]/.test(pattern)) {
61	    return false;
62	  }
63	  return true;
64	};
