1	import type { Root, Text } from "mdast";
2	import type { Position, Node as UnistNode } from "unist";
3	import type { TagNode, TagNodeData } from "@/types/markdown";
4	import { isTagChar, MAX_TAG_LENGTH } from "@/utils/tag-grammar";
5	
6	type Segment = { type: "text"; value: string } | { type: "tag"; value: string };
7	
8	// CommonMark "ASCII punctuation": the only characters a leading backslash can
9	// escape. A backslash before anything else is a literal backslash.
10	function isAsciiPunctuation(char: string): boolean {
11	  if (char.length !== 1) {
12	    return false;
13	  }
14	  const code = char.charCodeAt(0);
15	  return (
16	    (code >= 0x21 && code <= 0x2f) || // ! " # $ % & ' ( ) * + , - . /
17	    (code >= 0x3a && code <= 0x40) || // : ; < = > ? @
18	    (code >= 0x5b && code <= 0x60) || // [ \ ] ^ _ `
19	    (code >= 0x7b && code <= 0x7e) //    { | } ~
20	  );
21	}
22	
23	/**
24	 * Apply CommonMark backslash-unescaping to a raw source slice, tracking which
25	 * resulting characters came from an escape. `\#` yields a `#` flagged escaped,
26	 * so the tag lexer can tell a deliberately-escaped hash from a real tag.
27	 * Returns code points (not UTF-16 units) so astral characters stay intact.
28	 */
29	function unescapeBackslashes(source: string): { chars: string[]; escaped: boolean[] } {
30	  const codePoints = [...source];
31	  const chars: string[] = [];
32	  const escaped: boolean[] = [];
33	
34	  for (let i = 0; i < codePoints.length; i++) {
35	    if (codePoints[i] === "\\" && i + 1 < codePoints.length && isAsciiPunctuation(codePoints[i + 1])) {
36	      chars.push(codePoints[i + 1]);
37	      escaped.push(true);
38	      i++;
39	      continue;
40	    }
41	    chars.push(codePoints[i]);
42	    escaped.push(false);
43	  }
44	
45	  return { chars, escaped };
46	}
47	
48	/**
49	 * Split a run of characters into text/tag segments. `escaped[i]` marks a
50	 * character that came from a backslash escape: an escaped `#` can never start a
51	 * tag (so `\#NAS` stays literal text), matching the backend goldmark parser and
52	 * the editor's marked tokenizer, both of which honor the escape natively.
53	 */
54	function parseSegments(chars: string[], escaped: boolean[]): Segment[] {
55	  const segments: Segment[] = [];
56	  let i = 0;
57	
58	  while (i < chars.length) {
59	    if (chars[i] === "#" && !escaped[i] && i + 1 < chars.length && isTagChar(chars[i + 1])) {
60	      const prevChar = i > 0 ? chars[i - 1] : "";
61	      const nextChar = chars[i + 1];
62	
63	      if (prevChar === "#" || nextChar === "#" || nextChar === " ") {
64	        segments.push({ type: "text", value: chars[i] });
65	        i++;
66	        continue;
67	      }
68	
69	      let j = i + 1;
70	      while (j < chars.length && isTagChar(chars[j])) {
71	        j++;
72	      }
73	
74	      const tagContent = chars.slice(i + 1, j).join("");
75	
76	      const runeCount = [...tagContent].length;
77	      if (runeCount > 0 && runeCount <= MAX_TAG_LENGTH) {
78	        segments.push({ type: "tag", value: tagContent });
79	        i = j;
80	        continue;
81	      }
82	    }
83	
84	    // Consume a plain-text run up to the next tag-eligible (non-escaped) hash.
85	    let j = i + 1;
86	    while (j < chars.length && !(chars[j] === "#" && !escaped[j])) {
87	      j++;
88	    }
89	    segments.push({ type: "text", value: chars.slice(i, j).join("") });
90	    i = j;
91	  }
92	
93	  return segments;
94	}
95	
96	/**
97	 * Segment a text node, preferring the original source slice (where escapes are
98	 * still visible) over the post-escape `value`. The source-derived parse is only
99	 * trusted when it reconstructs `value` byte-for-byte; otherwise — entity
100	 * references, missing positions, upstream rewrites — we fall back to the
101	 * value-based parse, which is exactly the pre-escape-support behavior. This
102	 * makes escape support strictly additive: it never changes a node it can't
103	 * faithfully account for.
104	 */
105	function segmentsForTextNode(value: string, position: Position | undefined, source: string): Segment[] {
106	  const startOffset = position?.start?.offset;
107	  const endOffset = position?.end?.offset;
108	
109	  if (source && startOffset != null && endOffset != null) {
110	    const slice = source.slice(startOffset, endOffset);
111	    const { chars, escaped } = unescapeBackslashes(slice);
112	    if (chars.join("") === value) {
113	      return parseSegments(chars, escaped);
114	    }
115	  }
116	
117	  const chars = [...value];
118	  return parseSegments(
119	    chars,
120	    chars.map(() => false),
121	  );
122	}
123	
124	function createTagNode(tagValue: string): TagNode {
125	  const data: TagNodeData = {
126	    hName: "span",
127	    hProperties: {
128	      className: "tag",
129	      "data-tag": tagValue,
130	    },
131	    hChildren: [{ type: "text", value: `#${tagValue}` }],
132	  };
133	
134	  return {
135	    type: "tagNode",
136	    value: tagValue,
137	    data,
138	  } as TagNode;
139	}
140	
141	type ParentNode = UnistNode & { children: UnistNode[] };
142	
143	function isParentNode(node: UnistNode): node is ParentNode {
144	  return Array.isArray((node as { children?: unknown }).children);
145	}
146	
147	function isLinkNode(node: UnistNode): boolean {
148	  return node.type === "link" || node.type === "linkReference";
149	}
150	
151	function transformTagTextNodes(parent: ParentNode, insideLink: boolean, source: string): void {
152	  for (let index = 0; index < parent.children.length; index++) {
153	    const child = parent.children[index];
154	    const childInsideLink = insideLink || isLinkNode(child);
155	
156	    if (child.type === "text" && !childInsideLink) {
157	      const textNode = child as Text;
158	      const segments = segmentsForTextNode(textNode.value, textNode.position, source);
159	
160	      if (segments.every((seg) => seg.type === "text")) {
161	        continue;
162	      }
163	
164	      const newNodes = segments.map((segment) => {
165	        if (segment.type === "tag") {
166	          return createTagNode(segment.value);
167	        }
168	        return {
169	          type: "text",
170	          value: segment.value,
171	        } as Text;
172	      });
173	
174	      parent.children.splice(index, 1, ...(newNodes as UnistNode[]));
175	      index += newNodes.length - 1;
176	      continue;
177	    }
178	
179	    if (isParentNode(child)) {
180	      transformTagTextNodes(child, childInsideLink, source);
181	    }
182	  }
183	}
184	
185	type VFileLike = { value?: string | Uint8Array };
186	
187	export const remarkTag = () => {
188	  return (tree: Root, file: VFileLike) => {
189	    const source = typeof file?.value === "string" ? file.value : "";
190	    transformTagTextNodes(tree as ParentNode, false, source);
191	  };
192	};
