1	import { defaultKeymap, history, historyKeymap, indentWithTab } from "@codemirror/commands";
2	import { markdown } from "@codemirror/lang-markdown";
3	import { indentUnit } from "@codemirror/language";
4	import { Compartment, type Extension } from "@codemirror/state";
5	import { placeholder as cmPlaceholder, dropCursor, EditorView, type KeyBinding, keymap } from "@codemirror/view";
6	import { GFM } from "@lezer/markdown";
7	import { headingDecorations } from "./headingDecorations";
8	import { liftListItem, sinkListItem } from "./listIndent";
9	import { tagAutocomplete } from "./tagAutocomplete";
10	import { tagMentionDecorations } from "./tagMentionDecorations";
11	import { memoEditorTheme } from "./theme";
12	
13	// Key bindings layered below the autocomplete keymap so the completion popup's
14	// own Tab/Escape win while it is open. On a list item, Tab/Shift-Tab nest /
15	// outdent it (marker-aware, CommonMark-valid); elsewhere they fall through to
16	// indentWithTab's plain indent. Escape blurs the editor so keyboard users keep
17	// an escape hatch out of the otherwise Tab-trapping editor.
18	const editorKeys: KeyBinding[] = [
19	  {
20	    key: "Escape",
21	    run: (view) => {
22	      view.contentDOM.blur();
23	      return true;
24	    },
25	  },
26	  { key: "Tab", run: sinkListItem },
27	  { key: "Shift-Tab", run: liftListItem },
28	];
29	
30	export interface EditorExtensionsOptions {
31	  placeholder: string;
32	  onChange: (markdown: string) => void;
33	  onFiles: (files: File[]) => void;
34	  onUpdate: () => void;
35	  onSubmit: () => void;
36	  getTags: () => string[];
37	}
38	
39	export const placeholderCompartment = new Compartment();
40	
41	function clipboardFiles(event: ClipboardEvent): File[] {
42	  const clipboard = event.clipboardData;
43	  if (!clipboard) return [];
44	
45	  const itemFiles = Array.from(clipboard.items)
46	    .filter((item) => item.kind === "file")
47	    .map((item) => item.getAsFile())
48	    .filter((file): file is File => file !== null);
49	  return itemFiles.length > 0 ? itemFiles : Array.from(clipboard.files);
50	}
51	
52	export function buildEditorExtensions({
53	  placeholder,
54	  onChange,
55	  onFiles,
56	  onUpdate,
57	  onSubmit,
58	  getTags,
59	}: EditorExtensionsOptions): Extension[] {
60	  // Submitting must outrank defaultKeymap's own Mod-Enter (insertBlankLine): the save
61	  // shortcut ends the memo, it must not also edit the document. Meta and Ctrl are bound
62	  // explicitly (not via the platform-dependent Mod-) so Cmd+Enter and Ctrl+Enter both
63	  // submit everywhere, matching the historical window-level shortcut.
64	  const submit = () => {
65	    onSubmit();
66	    return true;
67	  };
68	  const submitKeys: KeyBinding[] = [
69	    { key: "Meta-Enter", run: submit },
70	    { key: "Ctrl-Enter", run: submit },
71	  ];
72	
73	  return [
74	    // Core editing behavior. These are the pieces from CM6 setup that this memo
75	    // editor uses, without enabling multi-cursor selection.
76	    history(),
77	    dropCursor(),
78	    // Indent with spaces (markdown), matching the 2-space bullet nesting.
79	    indentUnit.of("  "),
80	    markdown({ extensions: [GFM] }),
81	    ...memoEditorTheme,
82	    EditorView.lineWrapping,
83	    placeholderCompartment.of(cmPlaceholder(placeholder)),
84	    EditorView.domEventHandlers({
85	      paste: (event) => {
86	        const files = clipboardFiles(event);
87	        if (files.length === 0) return false;
88	        onFiles(files);
89	        return true;
90	      },
91	      drop: (event) => {
92	        const files = Array.from(event.dataTransfer?.files ?? []);
93	        if (files.length === 0) return false;
94	        onFiles(files);
95	        return true;
96	      },
97	    }),
98	    tagMentionDecorations,
99	    headingDecorations,
100	    // tagAutocomplete must precede the editing keymap so the completion popup's
101	    // Enter/Tab/arrow bindings win while it is open.
102	    tagAutocomplete(getTags),
103	    keymap.of([...submitKeys, ...editorKeys, indentWithTab, ...defaultKeymap, ...historyKeymap]),
104	    EditorView.updateListener.of((u) => {
105	      if (u.docChanged) onChange(u.state.doc.toString());
106	      // Toolbar active-state depends only on the doc and selection; skip the
107	      // getActiveFormats tree walk on focus/viewport/measure-only updates.
108	      if (u.docChanged || u.selectionSet) onUpdate();
109	    }),
110	  ];
111	}
