1	import { autocompletion, type CompletionContext, type CompletionResult } from "@codemirror/autocomplete";
2	import type { Extension } from "@codemirror/state";
3	import { TAG_CHAR_CLASS } from "@/utils/tag-grammar";
4	
5	const TAG_BEFORE = new RegExp(`#(${TAG_CHAR_CLASS}*)$`, "u");
6	
7	export function makeTagCompletionSource(getTags: () => string[]) {
8	  return (ctx: CompletionContext): CompletionResult | null => {
9	    const before = ctx.matchBefore(TAG_BEFORE);
10	    if (!before || (before.from === before.to && !ctx.explicit)) return null;
11	    const typed = before.text.slice(1).toLowerCase();
12	    // Require at least one character after `#` unless completion was explicitly
13	    // invoked, so a bare `#` doesn't pop the menu while typing.
14	    if (typed.length < 1 && !ctx.explicit) return null;
15	    const options = getTags()
16	      .filter((tag) => tag.toLowerCase().startsWith(typed))
17	      .map((tag) => ({ label: tag, type: "keyword" }));
18	    if (options.length === 0) return null;
19	    return { from: before.from + 1, options };
20	  };
21	}
22	
23	export function tagAutocomplete(getTags: () => string[]): Extension {
24	  return autocompletion({
25	    override: [makeTagCompletionSource(getTags)],
26	    icons: false,
27	  });
28	}
