26	func (s *APIV1Service) resolveMentionTargets(ctx context.Context, content string) (map[int32]*store.User, error) {
27		targets := make(map[int32]*store.User)
28		if content == "" {
29			return targets, nil
30		}
31	
32		data, err := s.MarkdownService.ExtractAll([]byte(content))
33		if err != nil {
34			return nil, errors.Wrap(err, "failed to extract mentions")
35		}
36		if len(data.Mentions) == 0 {
37			return targets, nil
38		}
39	
40		normal := store.Normal
41		users, err := s.Store.ListUsers(ctx, &store.FindUser{
42			UsernameList: data.Mentions,
43			RowStatus:    &normal,
44		})
45		if err != nil {
46			return nil, errors.Wrap(err, "failed to resolve mention users")
47		}
48	
49		for _, user := range users {
50			targets[user.ID] = user
51		}
52	
53		return targets, nil
54	}
